148	+        Fixtures.Rig rig = Fixtures.rig(helper, 1);
149	+        CoreBlockEntity core = helper.getBlockEntity(rig.core(), CoreBlockEntity.class);
150	+        helper.startSequence()
151	+                .thenWaitUntil(() -> helper.assertTrue(core.lastScan().formed(), "formed before the break"))
152	+                .thenExecute(() -> helper.getLevel().destroyBlock(helper.absolutePos(rig.power()), false))
153	+                .thenWaitUntil(() -> helper.assertValueEqual(core.lastScan().problem(), Problem.MISSING_POWER, "problem"))
154	+                .thenExecute(() -> helper.assertValueEqual(JadeInfo.coreLines(JadeInfo.core(core)),
155	+                        List.of(Component.translatable("modular_planters.jade.not_formed",
156	+                                Component.translatable("modular_planters.problem.missing_power"))), "lines"))
