221	+package io.github.julianperge.modular_planters.jade;
222	+
223	+import io.github.julianperge.modular_planters.MPConfig;
224	+import io.github.julianperge.modular_planters.blockentity.CoreBlockEntity;
225	+import io.github.julianperge.modular_planters.blockentity.PlanterBlockEntity;
226	+import java.util.List;
227	+import java.util.Locale;
228	+import net.minecraft.nbt.CompoundTag;
229	+import net.minecraft.network.chat.Component;
230	+
231	+// This class imports nothing from Jade, so the mod works without it and the GameTests cover the lines.
232	+public final class JadeInfo {
233	+    private JadeInfo() {
234	+    }
235	+
236	+    public static CompoundTag core(CoreBlockEntity core) {
237	+        CompoundTag data = new CompoundTag();
238	+        data.putBoolean("formed", core.lastScan().formed());
239	+        data.putInt("parts", core.lastScan().partCount());
240	+        data.putInt("cap", MPConfig.PART_CAP.get());
241	+        data.putString("problem", core.lastScan().problem().name());
242	+        return data;
243	+    }
244	+
245	+    public static List<Component> coreLines(CompoundTag data) {
246	+        if (data.getBoolean("formed").isEmpty()) {
247	+            return List.of();
248	+        }
249	+        if (data.getBooleanOr("formed", false)) {
250	+            return List.of(Component.translatable("modular_planters.jade.formed",
251	+                    data.getIntOr("parts", 0), data.getIntOr("cap", 0)));
252	+        }
253	+        return List.of(Component.translatable("modular_planters.jade.not_formed",
254	+                Component.translatable("modular_planters.problem." + data.getStringOr("problem", "").toLowerCase(Locale.ROOT))));
255	+    }
256	+
257	+    public static CompoundTag planter(PlanterBlockEntity planter) {
258	+        CompoundTag data = new CompoundTag();
259	+        data.putString("status", planter.status().name());
260	+        data.putInt("growing", planter.growing());
261	+        data.putInt("seeds", planter.seeds().size());
262	+        return data;
263	+    }
264	+
265	+    public static List<Component> planterLines(CompoundTag data) {
266	+        if (data.getString("status").isEmpty()) {
267	+            return List.of();
268	+        }
269	+        return List.of(
270	+                Component.translatable("modular_planters.status." + data.getStringOr("status", "").toLowerCase(Locale.ROOT)),
271	+                Component.translatable("modular_planters.jade.growing", data.getIntOr("growing", 0), data.getIntOr("seeds", 0)));
272	+    }
