+                Component.translatable("modular_planters.status." + data.getStringOr("status", "").toLowerCase(Locale.ROOT)),
+                Component.translatable("modular_planters.jade.growing", data.getIntOr("growing", 0), data.getIntOr("seeds", 0)));
+    }
+}

